-- Package 1: metadata only. No application/Auth rows or credentials are read.
with relations as (
  select c.*, n.nspname as schema_name from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname in ('public','app_private') and c.relkind in ('r','p','v','m','S')
), routines as (
  select p.*, n.nspname as schema_name from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where n.nspname in ('public','app_private')
    and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')
)
select jsonb_build_object(
  'captured_at', current_timestamp,
  'postgres_version', version(),
  'relations', (select jsonb_agg(jsonb_build_object('schema',schema_name,'name',relname,'kind',relkind,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'options',reloptions,'acl',relacl,'definition',case when relkind in ('v','m') then pg_get_viewdef(oid,true) end) order by schema_name,relname) from relations),
  'columns', (select jsonb_agg(jsonb_build_object('schema',r.schema_name,'table',r.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl) order by r.schema_name,r.relname,a.attnum) from relations r join pg_attribute a on a.attrelid=r.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=r.oid and d.adnum=a.attnum),
  'policies', (select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('public','app_private')),
  'functions', (select jsonb_agg(jsonb_build_object('schema',schema_name,'name',proname,'arguments',pg_get_function_identity_arguments(oid),'returns',pg_get_function_result(oid),'owner',pg_get_userbyid(proowner),'language',(select lanname from pg_language where oid=prolang),'security_definer',prosecdef,'volatility',provolatile,'config',proconfig,'acl',proacl,'body',prosrc,'definition',pg_get_functiondef(oid)) order by schema_name,proname,pg_get_function_identity_arguments(oid)) from routines),
  'triggers', (select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',pn.nspname||'.'||p.proname,'definition',pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where not t.tgisinternal and (n.nspname in ('public','app_private') or pn.nspname='app_private')),
  'constraints', (select jsonb_agg(jsonb_build_object('schema',r.schema_name,'table',r.relname,'name',c.conname,'type',c.contype,'validated',c.convalidated,'deferrable',c.condeferrable,'initially_deferred',c.condeferred,'definition',pg_get_constraintdef(c.oid,true)) order by r.schema_name,r.relname,c.conname) from pg_constraint c join relations r on r.oid=c.conrelid),
  'indexes', (select jsonb_agg(to_jsonb(i) order by schemaname,tablename,indexname) from pg_indexes i where schemaname in ('public','app_private')),
  'schemas', (select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) order by nspname) from pg_namespace where nspname in ('public','app_private')),
  'default_privileges', (select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(defaclrole),'schema',coalesce(n.nspname,'*'),'object_type',defaclobjtype,'acl',defaclacl) order by pg_get_userbyid(defaclrole),n.nspname,defaclobjtype) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace),
  'roles', (select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'bypass_rls',rolbypassrls,'can_login',rolcanlogin) order by rolname) from pg_roles where rolname in ('anon','authenticated','service_role','authenticator','postgres')),
  'role_memberships', (select jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'inherit',a.inherit_option,'set',a.set_option) order by r.rolname,m.rolname) from pg_auth_members a join pg_roles r on r.oid=a.roleid join pg_roles m on m.oid=a.member where m.rolname in ('anon','authenticated','service_role','authenticator','postgres')),
  'api_settings', (select jsonb_agg(jsonb_build_object('database',coalesce(d.datname,'*'),'role',coalesce(r.rolname,'*'),'setting',s.setting) order by d.datname,r.rolname,s.setting) from pg_db_role_setting x left join pg_database d on d.oid=x.setdatabase left join pg_roles r on r.oid=x.setrole cross join lateral unnest(x.setconfig) s(setting) where s.setting like 'pgrst.%' or s.setting like 'search_path=%'),
  'effective_relation_permissions', (select jsonb_agg(jsonb_build_object('role',role_name,'schema',r.schema_name,'relation',r.relname,'schema_usage',has_schema_privilege(role_name,r.relnamespace,'USAGE'),'select',has_table_privilege(role_name,r.oid,'SELECT'),'insert',has_table_privilege(role_name,r.oid,'INSERT'),'update',has_table_privilege(role_name,r.oid,'UPDATE'),'delete',has_table_privilege(role_name,r.oid,'DELETE'),'truncate',has_table_privilege(role_name,r.oid,'TRUNCATE')) order by role_name,r.schema_name,r.relname) from relations r cross join (values('anon'),('authenticated'),('service_role')) roles(role_name) where r.relkind<>'S'),
  'effective_column_permissions', (select jsonb_agg(jsonb_build_object('role',role_name,'schema',r.schema_name,'relation',r.relname,'column',a.attname,'select',has_column_privilege(role_name,r.oid,a.attnum,'SELECT'),'insert',has_column_privilege(role_name,r.oid,a.attnum,'INSERT'),'update',has_column_privilege(role_name,r.oid,a.attnum,'UPDATE')) order by role_name,r.schema_name,r.relname,a.attnum) from relations r join pg_attribute a on a.attrelid=r.oid and a.attnum>0 and not a.attisdropped cross join (values('anon'),('authenticated'),('service_role')) roles(role_name) where r.relkind<>'S'),
  'effective_function_permissions', (select jsonb_agg(jsonb_build_object('role',role_name,'schema',f.schema_name,'function',f.proname,'arguments',pg_get_function_identity_arguments(f.oid),'schema_usage',has_schema_privilege(role_name,f.pronamespace,'USAGE'),'execute',has_function_privilege(role_name,f.oid,'EXECUTE')) order by role_name,f.schema_name,f.proname,pg_get_function_identity_arguments(f.oid)) from routines f cross join (values('anon'),('authenticated'),('service_role')) roles(role_name)),
  'view_dependencies', (select jsonb_agg(distinct jsonb_build_object('view',v.schema_name||'.'||v.relname,'depends_on',tn.nspname||'.'||tc.relname)) from relations v join pg_rewrite rw on rw.ev_class=v.oid join pg_depend d on d.classid='pg_rewrite'::regclass and d.objid=rw.oid join pg_class tc on tc.oid=d.refobjid and d.refclassid='pg_class'::regclass join pg_namespace tn on tn.oid=tc.relnamespace where v.relkind='v' and tc.oid<>v.oid),
  'extensions', (select jsonb_agg(jsonb_build_object('name',extname,'version',extversion,'schema',n.nspname) order by extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
  'migrations', (select jsonb_agg(jsonb_build_object('version',version,'name',name,'statements',statements) order by version) from supabase_migrations.schema_migrations)
) as snapshot;
